document.addEventListener("DOMContentLoaded",()=>{initEarningsChart();initTrafficChart()});function initEarningsChart(){const ctx=document.getElementById("earningsChart");if(!ctx||typeof Chart==="undefined")return;new Chart(ctx,{type:"bar",data:{labels:["Ene","Feb","Mar","Abr","May","Jun","Jul","Ago","Sep","Oct","Nov","Dic"],datasets:[{label:"Ingresos 2026 ($)",data:[18e3,24e3,22e3,31e3,29e3,35e3,42e3,39e3,48e3,52e3,58e3,64e3],backgroundColor:"#556ee6",borderRadius:4,borderSkipped:false},{label:"Gastos 2026 ($)",data:[8e3,11e3,9500,14e3,12e3,15e3,18e3,16e3,21e3,22e3,24e3,26e3],backgroundColor:"#eff2f7",borderRadius:4,borderSkipped:false}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:"top",labels:{usePointStyle:true,boxWidth:8,font:{family:"Inter",size:12}}}},scales:{x:{grid:{display:false}},y:{grid:{color:"rgba(0,0,0,0.05)"}}}}})}function initTrafficChart(){const ctx=document.getElementById("trafficChart");if(!ctx||typeof Chart==="undefined")return;new Chart(ctx,{type:"doughnut",data:{labels:["Directo","Redes Sociales","Referidos","Búsqueda Orgánica"],datasets:[{data:[45,25,18,12],backgroundColor:["#556ee6","#34c38f","#f1b44c","#50a5f1"],borderWidth:0}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:"bottom",labels:{usePointStyle:true,boxWidth:8,font:{family:"Inter",size:11}}}},cutout:"70%"}})}